/**
 * direct_http_response — Direct producer for httpResponse shape, not delegating to web_resource..
 * Output shape: httpResponse
 */

import type { ResolverResult } from "./types.js";

export interface DirectHttpResponsePointer {
  type: "direct_http_response";
  [key: string]: unknown;
}

export async function resolveDirectHttpResponse(pointer: DirectHttpResponsePointer): Promise<ResolverResult> {

import type { ResolverResult } from "./types.js";

export interface DirectHttpResponsePointer {
  type: "direct_http_response";
  url: string;
}

export async function resolveDirectHttpResponse(
  pointer: DirectHttpResponsePointer,
): Promise<ResolverResult> {
  // Implement direct HTTP response logic here.
  // For now, it will return a mock response.
  return {
    shape: "httpResponse",
    body: {
      url: pointer.url,
      status: 200,
      headers: { "Content-Type": "text/plain" },
      body: `This is a direct response for ${pointer.url}`,
    },
  };
}

}

import { describe, it, expect } from "bun:test";
import { resolveDirectHttpResponse } from "../../src/resolvers/direct-http-response.js";

describe("direct_http_response resolver", () => {
  it("returns a well-formed result for the httpResponse shape", async () => {
    const r = await resolveDirectHttpResponse({ type: "direct_http_response" });
    expect(typeof r.shape).toBe("string");
    expect(r).toHaveProperty("body");
  });
});

